jsx_api.example_usage:
// App root:
<ToastProvider>
  <App />
  <ToastViewport />
</ToastProvider>

// Inside any component:
const { toast } = useToast();
toast({ type: 'success', message: 'Saved.' });
toast({ type: 'error', message: 'Failed.' });

jsx_api.react_example:
import * as Toast from '@radix-ui/react-toast';
// Provider at root:
<Toast.Provider swipeDirection="right">
  {children}
  <Toast.Viewport className="ds-toast-container" />
</Toast.Provider>
// Toast item:
<Toast.Root className="ds-toast success">
  <Toast.Title>{message}</Toast.Title>
  <Toast.Action asChild altText="Dismiss"><button className="ds-toast-dismiss">×</button></Toast.Action>
</Toast.Root>
